select energy_manager.load_cards($cards$[
{"id":"p1-b07-038","paper":1,"topic":"Financial management","kind":"problem","front":"Two projects each cost ₹30,000 and have a 10-year life; discount rate 8%. Project 1 saves ₹6,000 every year. Project 2 saves ₹6,600 in years 1–2, ₹6,300 in years 3–4, ₹6,000 in years 5–6, ₹5,700 in years 7–8 and ₹5,400 in years 9–10. Both total ₹60,000. Which is better by NPV?","back":"NPV₁ ≈ ₹10,254; NPV₂ ≈ ₹10,867. Project 2 is preferred.","explain":"Total savings are equal, but Project 2 earns more in the early years, and money received earlier is worth more after discounting. Comparing total savings alone could not separate these two projects.","flash":false,"source":"BEE Book 1 Ch 07 p198","steps":[{"prompt":"List the 8% discount factors 1/(1.08)ᵗ for years 1–10.","answer":"0.926, 0.857, 0.794, 0.735, 0.681, 0.630, 0.583, 0.540, 0.500, 0.463 (sum 6.709)","explain":"Factor for year 0 (the investment) is 1."},{"prompt":"NPV of Project 1.","answer":"−30,000 + 6,000 × 6.709 = −30,000 + 40,254 = ₹10,254","explain":"Equal yearly savings can be multiplied by the sum of the factors."},{"prompt":"Present value of Project 2's savings.","answer":"6,600 × (0.926+0.857) + 6,300 × (0.794+0.735) + 6,000 × (0.681+0.630) + 5,700 × (0.583+0.540) + 5,400 × (0.500+0.463) = 11,768 + 9,633 + 7,866 + 6,401 + 5,200 = ₹40,868","explain":"Each pair of years has the same saving."},{"prompt":"NPV of Project 2.","answer":"−30,000 + 40,868 ≈ ₹10,867","explain":"The book shows ₹10,867 (rounding of factors)."},{"prompt":"Choose.","answer":"Project 2 (higher NPV)","explain":"Front-loaded savings are worth more in present-value terms."}],"order":1364},
{"id":"p1-b07-039","paper":1,"topic":"Financial management","kind":"problem","front":"A project costs ₹20,000 and returns ₹6,000, 5,500, 5,000, 4,500, 4,000 and 4,000 in years 1–6. The firm's cost of capital is 8%. Find the NPV at 8% and the IRR by interpolation between 12% and 13%.","back":"NPV at 8% ≈ ₹2,791. NPV at 12% ≈ +₹457, at 13% ≈ −₹65, so IRR ≈ 12.9% (the book gives 12.88%).","explain":"IRR is the discount rate that makes NPV zero; you raise the rate until NPV changes sign, then interpolate. The printed book shows +₹495 at 12%, but its own factors give about +₹460; either value interpolates to ≈ 12.88%. Since IRR exceeds the 8% cost of capital, the project is sound.","flash":false,"source":"BEE Book 1 Ch 07 p200","steps":[{"prompt":"NPV at 8% (factors 0.926, 0.857, 0.794, 0.735, 0.681, 0.630).","answer":"−20,000 + 5,556 + 4,714 + 3,970 + 3,308 + 2,724 + 2,520 = ₹2,791","explain":"Positive NPV, so the IRR is above 8%; increase the rate."},{"prompt":"NPV at 12% (factors 0.893, 0.797, 0.712, 0.636, 0.567, 0.507).","answer":"−20,000 + 5,358 + 4,384 + 3,560 + 2,862 + 2,268 + 2,028 ≈ +₹460 (exact ≈ +₹457)","explain":"Still positive, so IRR > 12%."},{"prompt":"NPV at 13% (factors 0.885, 0.783, 0.693, 0.613, 0.543, 0.480).","answer":"≈ −₹65","explain":"Negative, so IRR lies between 12% and 13%. (At 16% NPV ≈ −₹1,508.)"},{"prompt":"Interpolate.","answer":"IRR = 12 + 457 × (13 − 12) ÷ (457 − (−65)) = 12 + 457/522 ≈ 12.88%","explain":"IRR = lower rate + NPV_low × (rate gap) ÷ (NPV_low − NPV_high)."},{"prompt":"Judge.","answer":"IRR ≈ 12.9% > 8% cost of capital → accept","explain":"A project is sound when IRR exceeds the cost of money."}],"order":1365},
{"id":"p1-b07-040","paper":1,"topic":"Financial management","kind":"problem","front":"An oil-fired reheating furnace heats 12 t/h of steel billets from 40°C to 1220°C at 28% efficiency, 4,700 h/year. Billet specific heat 0.12 kcal/kg°C; furnace oil GCV 10,000 kcal/kg, density 0.94 kg/L, cost ₹45/L. Ceramic fibre insulation (₹20 lakh) raises efficiency to 30%. Find the oil use per tonne, hourly saving, simple payback, and the maximum justified investment at 16% over 6 years.","back":"≈53.8 L oil/t; saving ≈ ₹1,936/h (₹91 lakh/yr); payback ≈ 0.22 yr (≈2.6 months); maximum investment ≈ ₹3.35 crore.","explain":"The book's working shows the payback as 0.352 years (4.2 months), but 20,00,000 ÷ (1,936 × 4,700) = 0.22 years, so 0.22 years is the figure its own data support. Part (e) is the present value of ₹91 lakh/year for 6 years at 16%: the most you could invest and still earn a 16% IRR.","flash":false,"source":"BEE Book 1 Ch 07 p215","steps":[{"prompt":"Heat needed by the billets per hour.","answer":"m·Cp·ΔT = 12,000 × 0.12 × (1220 − 40) = 16,99,200 kcal/h","explain":"Sensible heat of the stock."},{"prompt":"Furnace oil per tonne of billets at 28%.","answer":"16,99,200 ÷ 12 = 1,41,600 kcal/t; ÷ 0.28 = 5,05,714 kcal/t; ÷ 10,000 = 50.57 kg; ÷ 0.94 = 53.8 L/t","explain":"Input = useful heat ÷ efficiency."},{"prompt":"Hourly saving when efficiency goes to 30%.","answer":"53.79 × (1 − 0.28/0.30) × 45 = ₹161.4 per tonne; × 12 t/h = ₹1,936/h","explain":"Fuel needed falls in the ratio of the efficiencies."},{"prompt":"Simple payback.","answer":"Annual saving = 1,936 × 4,700 = ₹91.0 lakh; 20 lakh ÷ 91.0 lakh ≈ 0.22 yr ≈ 2.6 months","explain":"Capital ÷ annual net savings."},{"prompt":"Maximum investment for 16% IRR over 6 years.","answer":"91.0 × (0.862 + 0.743 + 0.641 + 0.552 + 0.476 + 0.410) = 91.0 × 3.684 ≈ ₹335 lakh = ₹3.35 crore","explain":"At this investment the NPV at 16% is zero, i.e. IRR = 16%."}],"order":1366},
{"id":"p1-b07-041","paper":1,"topic":"Financial management","kind":"problem","front":"Find the NPV at 16% of a project costing ₹50,000 at the start of year 1 that saves ₹23,000 at the end of year 1 and ₹36,000 at the end of year 2.","back":"NPV ≈ −₹3,419 (negative, so the project fails at 16%).","explain":"This is the chapter's objective question 7; the magnitude matches option (d) 3,419, but the sign is negative because the discounted savings are less than the investment.","flash":false,"source":"BEE Book 1 Ch 07 p217","steps":[{"prompt":"Discount year-1 saving.","answer":"23,000 ÷ 1.16 = ₹19,828","explain":"PV = FV ÷ (1 + i)ⁿ with n = 1."},{"prompt":"Discount year-2 saving.","answer":"36,000 ÷ 1.16² = 36,000 ÷ 1.3456 = ₹26,754","explain":"n = 2."},{"prompt":"Add the investment.","answer":"NPV = −50,000 + 19,828 + 26,754 = −₹3,418 ≈ −₹3,419","explain":"The investment at t = 0 is not discounted."},{"prompt":"Decide.","answer":"Negative NPV → reject at a 16% discount rate","explain":"NPV < 0 means the return standard is not met."}],"order":1367},
{"id":"p1-b07-042","paper":1,"topic":"Financial management","kind":"problem","front":"₹10,000 is deposited at the start of a year at 6% annual interest. How much is in the account at the end of year 5 if nothing is withdrawn?","back":"₹13,382.","explain":"This is compounding, the reverse of discounting. Simple interest would give only ₹13,000, a common wrong option.","flash":false,"source":"BEE Book 1 Ch 07 p217","steps":[{"prompt":"Choose the formula.","answer":"FV = PV × (1 + i)ⁿ","explain":"Interest earns interest each year."},{"prompt":"Substitute.","answer":"10,000 × (1.06)⁵","explain":"n = 5 years."},{"prompt":"Calculate.","answer":"1.06⁵ = 1.3382 → ₹13,382","explain":"Not 10,000 × (1 + 5 × 0.06) = 13,000."}],"order":1368},
{"id":"p1-b07-043","paper":1,"topic":"Financial management","kind":"problem","front":"A company invests ₹10 lakh at the start of year 1 in an energy project giving a constant net cash flow of ₹2 lakh a year for 10 years. It expects an IRR of at least 26%. Does the project meet this, and what is its IRR?","back":"No. NPV at 26% ≈ −₹3.07 lakh; the IRR is about 15%.","explain":"For equal annual cash flows, the IRR is the rate at which the annuity factor equals investment ÷ annual flow (here 5). A 26% rate gives a 10-year factor of only about 3.47, far short of 5.","flash":false,"source":"BEE Book 1 Ch 07 p218","steps":[{"prompt":"Find the required annuity factor.","answer":"10 ÷ 2 = 5.0","explain":"At the IRR, 2 × (sum of discount factors) = 10."},{"prompt":"Test 26%.","answer":"Sum of factors (10 yr, 26%) ≈ 3.47; NPV = −10 + 2 × 3.47 ≈ −₹3.07 lakh","explain":"Negative NPV, so IRR < 26%: expectation not met."},{"prompt":"Test 15% and 16%.","answer":"NPV at 15% ≈ +₹0.04 lakh; at 16% ≈ −₹0.33 lakh","explain":"Sign changes between 15% and 16%."},{"prompt":"Interpolate.","answer":"IRR ≈ 15 + 0.04 ÷ (0.04 + 0.33) ≈ 15.1%","explain":"About 15%, well below the 26% target."}],"order":1369},
{"id":"p1-b07-044","paper":1,"topic":"Financial management","kind":"problem","front":"An energy-saving retrofit costs ₹1,00,000. It saves 6,000 kWh/year at ₹3/kWh, ₹3,800/year in demand charges and ₹2,000/year in maintenance. Rates stay constant and life is 10 years. Find the NPV at 12%.","back":"NPV ≈ +₹34,475, so the retrofit is worthwhile.","explain":"All three saving streams are added into one annual net cash flow. With equal annual flows, NPV = −investment + annual saving × sum of discount factors.","flash":false,"source":"BEE Book 1 Ch 07 p218","steps":[{"prompt":"Annual energy saving.","answer":"6,000 × 3 = ₹18,000","explain":"kWh saved × energy rate."},{"prompt":"Total annual net saving.","answer":"18,000 + 3,800 + 2,000 = ₹23,800","explain":"Include demand and maintenance savings."},{"prompt":"Sum of 12% discount factors for 10 years.","answer":"≈ 5.650","explain":"Σ 1/(1.12)ᵗ for t = 1…10."},{"prompt":"NPV.","answer":"−1,00,000 + 23,800 × 5.650 = −1,00,000 + 1,34,475 ≈ +₹34,475","explain":"Positive NPV → accept."}],"order":1370},
{"id":"p1-b07-045","paper":1,"topic":"Financial management","kind":"problem","front":"100 fused 60 W incandescent bulbs are replaced by 12 W CFLs instead of new incandescent bulbs, for 4,000 h/year. Energy charge ₹4/kWh; demand charge ₹250/kVA/month (take unity power factor). Find the annual cost saving. Incandescent bulb ₹10 (life 1,000 h), CFL ₹100 (life 4,000 h): find the simple payback.","back":"Saving ≈ ₹91,200/year (₹76,800 energy + ₹14,400 demand). Extra lamp cost ₹6,000/year, so payback ≈ 0.066 yr (about 3–4 weeks).","explain":"This is the book's short question S-1; the book gives no answer, so this solution assumes unity power factor (kVA = kW) and that each bulb's demand counts every month. Over 4,000 h one CFL replaces four incandescent bulbs, so the extra outlay is only ₹100 − ₹40 per point.","flash":false,"source":"BEE Book 1 Ch 07 p218","steps":[{"prompt":"Load reduction.","answer":"100 × (60 − 12) W = 4,800 W = 4.8 kW (≈ 4.8 kVA at unity PF)","explain":"Saving per lamp is 48 W."},{"prompt":"Energy cost saving.","answer":"4.8 × 4,000 = 19,200 kWh × ₹4 = ₹76,800/year","explain":"kW × hours × tariff."},{"prompt":"Demand charge saving.","answer":"4.8 × 250 × 12 = ₹14,400/year; total ₹91,200/year","explain":"Demand charge is per kVA per month."},{"prompt":"Incremental lamp cost.","answer":"Over 4,000 h: 4 bulbs × ₹10 = ₹40 vs 1 CFL ₹100 → extra ₹60 × 100 = ₹6,000","explain":"Compare against the alternative of buying new incandescent bulbs."},{"prompt":"Simple payback.","answer":"6,000 ÷ 91,200 ≈ 0.066 yr ≈ 24 days","explain":"Capital (extra cost) ÷ annual net saving."}],"order":1371},
{"id":"p1-075","paper":1,"topic":"Project management","kind":"fact","front":"What is a Work Breakdown Structure (WBS)?","back":"A hierarchical breakdown of a complex project into smaller, manageable tasks or work packages that can be scheduled, costed and assigned.","explain":"The WBS is the basis for estimating time and cost and for building network diagrams. The lowest level should be a work package that one person or team can own.","flash":false,"source":"BEE 2025 P1 Q22","order":1372},
{"id":"p1-076","paper":1,"topic":"Project management","kind":"fact","front":"What is the main limitation of a Gantt chart?","back":"It does not clearly show logical dependencies between activities, so it cannot identify the critical path.","explain":"Gantt (bar) charts show each activity's start, duration and finish against a calendar, which makes them good for communicating progress. Network methods (CPM/PERT) are needed to analyse dependencies and float.","flash":false,"source":"BEE 2025 P1 Q23","order":1373},
{"id":"p1-077","paper":1,"topic":"Project management","kind":"fact","front":"How does CPM differ from PERT?","back":"CPM is deterministic: each activity has one fixed duration, and the method is often used for time-cost trade-offs. PERT is probabilistic: it uses three time estimates per activity, te = (a + 4m + b) ÷ 6, with variance ((b − a)/6)².","explain":"PERT suits R&D or new projects where durations are uncertain. It gives the probability of finishing by a target date. CPM suits repetitive projects such as construction where durations are well known. Both identify the critical path.","flash":false,"source":"BEE 2025 P1 Q27, S3","order":1374},
{"id":"p1-078","paper":1,"topic":"Project management","kind":"fact","front":"What is the critical path, and which common statement about it is false?","back":"The critical path is the longest-duration path through the network. Its length is the minimum time needed to complete the project, and its activities have zero float. False statement: 'it is the maximum time required to complete the project'.","explain":"Any delay to a critical activity delays the whole project, so management attention goes there. There can be more than one critical path, and the critical path can shift as activities progress.","flash":false,"source":"BEE 2024 P1 Q15","order":1375},
{"id":"p1-079","paper":1,"topic":"Project management","kind":"fact","front":"How is slack (float) of an activity calculated? Is an activity with ES = 8 and LS = 10 critical?","back":"Slack = LS − ES = LF − EF. Here slack = 10 − 8 = 2 days, so the activity is NOT critical (critical activities have zero slack).","explain":"Example: LS = 8, LF = 12, EF = 9 → slack = LF − EF = 12 − 9 = 3 weeks. The forward pass gives ES/EF (take the maximum of predecessors' EF); the backward pass gives LS/LF (take the minimum of successors' LS).","flash":false,"source":"BEE 2024 P1 Q17; BEE 2025 P1 Q28, Q30","order":1376},
{"id":"p1-080","paper":1,"topic":"Project management","kind":"fact","front":"Why is a dummy activity used in a project network (activity-on-arrow) diagram?","back":"To show a logical dependency, or to keep two activities that share the same start and end nodes distinct. A dummy has zero duration and uses no resources.","explain":"Dummies are drawn as dashed arrows. They only preserve correct precedence logic; they do not change the project duration.","flash":false,"source":"BEE 2025 P1 Q24","order":1377},
{"id":"p1-081","paper":1,"topic":"Project management","kind":"problem","front":"Activities (duration in weeks; predecessors): A 4 (–), B 6 (–), C 3 (A), D 5 (A), E 4 (B, C), F 2 (D, E). Find ES, EF, LS, LF and slack for each activity, the critical path, and the project duration.","back":"Critical path A–C–E–F, duration 13 weeks. Slack: B = 1 week, D = 2 weeks; all others 0.","explain":"The forward pass gives the earliest times (take the maximum EF of predecessors). The backward pass from the project end gives the latest times (take the minimum LS of successors). Activities with zero slack form the critical path, the longest path through the network.","steps":[{"prompt":"Forward pass for A, B, C, D.","answer":"A: ES 0, EF 4; B: ES 0, EF 6; C: ES 4, EF 7; D: ES 4, EF 9","explain":"EF = ES + duration; ES = maximum EF of predecessors."},{"prompt":"Forward pass for E and F.","answer":"E: ES = max(6, 7) = 7, EF 11; F: ES = max(9, 11) = 11, EF 13 → project = 13 weeks","explain":"Project duration = EF of the last activity."},{"prompt":"Backward pass.","answer":"F: LF 13, LS 11; E: LF 11, LS 7; D: LF 11, LS 6; C: LF 7, LS 4; B: LF 7, LS 1; A: LF = min(4, 6) = 4, LS 0","explain":"LS = LF − duration; LF = minimum LS of successors."},{"prompt":"Find slack and the critical path.","answer":"Slack (LS − ES): A 0, B 1, C 0, D 2, E 0, F 0 → critical path A–C–E–F = 4+3+4+2 = 13 weeks","explain":"Zero-slack activities are critical."}],"flash":false,"source":"BEE 2025 P1 L1; BEE 2024 P1 L5 (modified)","order":1378},
{"id":"p1-082","paper":1,"topic":"Project management","kind":"problem","front":"PERT time estimates in weeks (optimistic a, most likely m, pessimistic b): A (start) 2-4-6; B (after A) 3-5-13; C (start) 4-6-8; D (after C) 2-3-4; E (after B and D) 1-2-3. Find the expected time of each activity, the critical path, the expected project duration, and its standard deviation.","back":"te: A 4, B 6, C 6, D 3, E 2. Critical path A–B–E = 12 weeks; σ ≈ 1.83 weeks.","explain":"PERT uses a beta-distribution approximation: te = (a + 4m + b)/6 and variance = ((b − a)/6)². Add up the variances along the critical path and take the square root to get the project's standard deviation, which is used to estimate the probability of meeting a deadline.","steps":[{"prompt":"Expected times.","answer":"A (2+16+6)/6 = 4; B (3+20+13)/6 = 6; C (4+24+8)/6 = 6; D (2+12+4)/6 = 3; E (1+8+3)/6 = 2","explain":"te = (a + 4m + b) ÷ 6."},{"prompt":"Path lengths.","answer":"A–B–E = 4+6+2 = 12; C–D–E = 6+3+2 = 11","explain":"The critical path is the longest path."},{"prompt":"Variances on the critical path.","answer":"A (4/6)² = 0.444; B (10/6)² = 2.778; E (2/6)² = 0.111; total = 3.333","explain":"σ² = ((b − a)/6)²."},{"prompt":"Project standard deviation.","answer":"σ = √3.333 = 1.83 weeks; expected duration = 12 weeks","explain":"Add variances (not standard deviations), then take the square root."}],"flash":false,"source":"syllabus","order":1379},
{"id":"p1-b08-001","paper":1,"topic":"Project management","kind":"fact","front":"How does the BEE book define a project, and why is a project 'temporary' and 'unique'?","back":"A 'temporary endeavour undertaken to create a unique product or service'. Temporary because it has a definite beginning and end; unique because its output differs in some distinguishing way from similar products or services.","explain":"The book's example is designing, installing and commissioning a cogeneration system in an industry. A project manager oversees the contractors and manages the schedule and budget.","flash":true,"source":"BEE Book 1 Ch 08 p221","order":1380},
{"id":"p1-b08-002","paper":1,"topic":"Project management","kind":"fact","front":"What is the objective of project management?","back":"To optimise project cost, time and quality.","explain":"Project management principles and techniques help finish projects on schedule, within budget and to specification, while supporting other organisational goals such as productivity, quality and cost-effectiveness.","flash":true,"source":"BEE Book 1 Ch 08 p221","order":1381},
{"id":"p1-b08-003","paper":1,"topic":"Project management","kind":"fact","front":"Name the six steps of the Project Development Cycle (PDC).","back":"1) Project identification and screening, 2) Technical design, 3) Financing, 4) Contracting, 5) Implementation, 6) Performance monitoring.","explain":"The chapter is organised around these steps. Energy-related projects are noted as generally low-risk, both in the means of achieving change and in its result.","flash":false,"source":"BEE Book 1 Ch 08 p221","order":1382},
{"id":"p1-b08-004","paper":1,"topic":"Project management","kind":"fact","front":"How do internal and external identification of energy-saving projects differ?","back":"Internal: the facility manager identifies opportunities during day-to-day energy management or from detailed audits. External: systematic audits by a reputable energy consultant, ESCO or industry organisation.","explain":"Both routes feed the first step of the project development cycle, after which the opportunities are screened and ranked.","flash":false,"source":"BEE Book 1 Ch 08 p222","order":1383},
{"id":"p1-b08-005","paper":1,"topic":"Project management","kind":"fact","front":"What criteria should be used to screen and rank energy-saving project opportunities?","back":"Economic feasibility (IRR, NPV, cash flow, average payback); sustainability of savings over equipment life; ease of quantifying, monitoring and verifying savings; availability of technology and ease of adapting it to Indian conditions; other environmental and social benefits (e.g. lower GHG and SO₂ emissions).","explain":"Screening ensures that limited capital goes to projects whose savings are real, lasting and measurable, not just economically attractive on paper.","flash":false,"source":"BEE Book 1 Ch 08 p222","order":1384},
{"id":"p1-b08-006","paper":1,"topic":"Project management","kind":"fact","front":"What must a technical feasibility study for an energy project identify?","back":"Proposed technologies and measures; supply chain for products and materials; special technical difficulties and skills needed; preliminary designs with schematics, manufacturer details and capital cost estimates; and an organisational and management plan with timetable, staffing, training and logistics.","explain":"A sound technical feasibility study is what makes the project a viable investment in the eyes of management and lenders.","flash":false,"source":"BEE Book 1 Ch 08 p222","order":1385},
{"id":"p1-b08-007","paper":1,"topic":"Project management","kind":"fact","front":"Which internal sources of project funds does the BEE book list, and when may the revenue budget be used?","back":"Direct cash from company reserves, the revenue budget (if payback is less than one year), and new share capital.","explain":"Low-cost measures, treated as mini-projects, should get top priority, and the present system should be running efficiently before money is spent. Very short-payback measures can be funded from the operating (revenue) budget instead of capital.","flash":false,"source":"BEE Book 1 Ch 08 p223","order":1386},
{"id":"p1-b08-008","paper":1,"topic":"Project management","kind":"fact","front":"List the external sources of funds for an energy project.","back":"Bank loans, leasing arrangements, payment by savings (a deal with the equipment supplier), energy services contracts, and private finance initiatives.","explain":"Lenders such as banks or national development banks will want, besides company assets and credit lines, a pro forma financial worksheet showing project cash flows, NPV and IRR.","flash":false,"source":"BEE Book 1 Ch 08 p223","order":1387},
{"id":"p1-b08-009","paper":1,"topic":"Project management","kind":"fact","front":"What good practices does the BEE book recommend for managing contracts in a project?","back":"Ensure every contractor is competent (one weak link can delay all); make contractors and suppliers prepare realistic, detailed resource and time plans matching the project plan; impose (graduated) penalties and offer incentives; help them with genuine problems as partners; keep the right to off-load contracts in time if delays are expected.","explain":"A substantial part of most projects is done through contracts, so contract management is critical to successful implementation.","flash":false,"source":"BEE Book 1 Ch 08 p223","order":1388},
{"id":"p1-b08-010","paper":1,"topic":"Project management","kind":"fact","front":"In a traditional (fixed-price or lump-sum) contract, who carries the risk, and when is it appropriate?","back":"The contractor takes the risk of unforeseen problems in exchange for a larger profit. It suits dealing with unknown vendors or work the project manager expects to be risky.","explain":"All specifications are given to the contractor, who buys and installs equipment at a fixed price or at cost plus a mark-up.","flash":false,"source":"BEE Book 1 Ch 08 p224","order":1389},
{"id":"p1-b08-011","paper":1,"topic":"Project management","kind":"fact","front":"What are 'extended technical guarantee/service' and 'extended financing terms' contracts?","back":"Extended guarantee/service: extended performance guarantees on selected equipment and/or service and maintenance agreements. Extended financing: the contractor offers an extended lease or other financing with payments based on expected savings.","explain":"These sit between a traditional contract and full performance contracts, in which savings themselves are guaranteed or shared.","flash":false,"source":"BEE Book 1 Ch 08 p224","order":1390},
{"id":"p1-b08-012","paper":1,"topic":"Project management","kind":"fact","front":"In a shared savings performance contract (as described in the project management chapter), who provides finance and how is the contractor paid?","back":"The contractor provides the financing and is paid an agreed fraction of actual savings as they are achieved; this payment pays down the debt cost of equipment and services.","explain":"In a guaranteed saving performance contract, all or part of the savings is guaranteed by the contractor, and all or part of the cost of equipment and services is paid down out of savings as they are achieved.","flash":false,"source":"BEE Book 1 Ch 08 p224","order":1391},
{"id":"p1-b08-013","paper":1,"topic":"Project management","kind":"fact","front":"Why is a performance monitoring system needed, and what three principles should it follow?","back":"It helps anticipate deviations from the plan, analyse emerging problems and take corrective action. It should focus sharply on critical aspects, emphasise physical milestones rather than financial targets, and be kept simple.","explain":"The exam likes the trap that monitoring should stress financial targets – the book says physical milestones.","flash":false,"source":"BEE Book 1 Ch 08 p225","order":1392},
{"id":"p1-b08-014","paper":1,"topic":"Project management","kind":"fact","front":"Once a project is commissioned, how is a periodic performance review useful?","back":"It shows how realistic the project's assumptions were, gives a documented log of experience for future decisions, suggests corrective action from actual performance, and helps uncover judgmental biases.","explain":"The review compares actual with projected performance and acts as a feedback device.","flash":false,"source":"BEE Book 1 Ch 08 p225","order":1393},
{"id":"p1-b08-015","paper":1,"topic":"Project management","kind":"fact","front":"When is the Work Breakdown Structure (WBS) developed relative to other planning steps, and how can it be displayed?","back":"Before dependencies are identified and activity durations estimated; it is used to identify tasks before building Gantt charts and CPM/PERT networks. It can be shown as a tree, list or table.","explain":"The level of breakdown depends on the type of project and the management style. In budgeting, costs are estimated at the work-package level and rolled up to higher WBS levels.","flash":false,"source":"BEE Book 1 Ch 08 p226","order":1394},
{"id":"p1-b08-016","paper":1,"topic":"Project management","kind":"fact","front":"Who developed the Gantt chart, what was an early application, and what form does it take?","back":"Henry Gantt, during the era of scientific management; an early use was tracking shipbuilding projects. It is a horizontal bar chart with time on the horizontal axis.","explain":"Each task is a bar whose length shows its duration; rows show start and end dates. Time units are typically weeks or months.","flash":true,"source":"BEE Book 1 Ch 08 p226","order":1395},
{"id":"p1-b08-017","paper":1,"topic":"Project management","kind":"fact","front":"How can a basic Gantt chart be enhanced to show more information?","back":"A vertical line marking the present date (showing tasks running together and simultaneous resource needs); shading bars as progress is made; link lines or colour codes for dependencies; resource allocation per task; milestones.","explain":"The basic chart's weakness is that it does not show logical dependencies well; network diagrams show logic clearly but have no time-scale axis.","flash":false,"source":"BEE Book 1 Ch 08 p227","order":1396},
{"id":"p1-b08-018","paper":1,"topic":"Project management","kind":"fact","front":"Define activity, event and network in project networking.","back":"Activity: a task required by the project that uses resources and consumes time. Event: the beginning or ending point of one or more activities (a node). Network: the combination of all project activities and events.","explain":"A project network shows graphically which tasks must precede or follow others, making it a powerful planning and control tool.","flash":false,"source":"BEE Book 1 Ch 08 p227","order":1397},
{"id":"p1-b08-019","paper":1,"topic":"Project management","kind":"fact","front":"How do activity-on-arrow (AOA) and activity-on-node (AON) networks differ? Which is used in software packages?","back":"AOA: activities are arrows joined at event nodes (circles). AON: activities are nodes, with dependencies drawn as arrows between them. AON is used in project management software.","explain":"In AOA a dashed dummy activity is needed when two activities would share the same start and end events, to show the correct dependency. The CPM network was originally developed as AON.","flash":false,"source":"BEE Book 1 Ch 08 p227","order":1398},
{"id":"p1-b08-020","paper":1,"topic":"Project management","kind":"fact","front":"Who developed the Critical Path Method (CPM), when, and for what purpose?","back":"DuPont, in 1957, to manage shutting down chemical plants for maintenance and restarting them.","explain":"CPM gives a graphical view of the project, predicts the time required, and shows which activities are critical to the schedule and which are not.","flash":true,"source":"BEE Book 1 Ch 08 p228","order":1399}
]$cards$::jsonb);
